//! The Rust side of `ui/*.slint`, generated by `build.rs`. A crate of its own, so an edit to `postvak-gui` does not
//! compile the generated code again.
#![allow(
    unsafe_code,
    clippy::all,
    clippy::expect_used,
    clippy::panic,
    clippy::todo,
    clippy::unwrap_used,
    reason = "generated by Slint, not written here; an allow, as which lints it trips changes with the Slint version"
)]

slint::include_modules!();
